window.I18N = (function () {
  var lang = localStorage.getItem('meridian-lang') || 'es';
  var dict = {};

  // DMXAiStudio feed: ?brand=<id> merges per-brand content (generated by the panel into
  // localStorage 'dmxbook:<id>') over the bundled demo dict. Missing keys fall back to the demo.
  function deepMerge(t, s) {
    for (var k in s) {
      if (s[k] && typeof s[k] === 'object' && !Array.isArray(s[k])) { t[k] = t[k] || {}; deepMerge(t[k], s[k]); }
      else { t[k] = s[k]; }
    }
    return t;
  }
  function brandOverrides(l) {
    var brand = new URLSearchParams(location.search).get('brand');
    if (!brand) return null;
    try { return (JSON.parse(localStorage.getItem('dmxbook:' + brand) || '{}') || {})[l] || null; }
    catch (e) { return null; }
  }

  function load(l) {
    return fetch('assets/i18n/' + l + '.json')
      .then(function (r) { return r.json(); })
      .then(function (d) { dict = d; var ov = brandOverrides(l); if (ov) deepMerge(dict, ov); })
      .catch(function () { dict = {}; });
  }

  var ready = load(lang);

  function t(key) {
    var v = key.split('.').reduce(function (o, k) { return o && o[k]; }, dict);
    if (v == null) return key;
    // Substitute the demo brand name in bundled copy with the active brand (DMXAiStudio feed).
    if (typeof v === 'string') {
      var brand = (window.MERIDIAN && window.MERIDIAN.brand) || 'Meridian';
      if (brand !== 'Meridian') v = v.replace(/Meridian/g, brand);
    }
    return v;
  }

  function apply(root) {
    root = root || document;
    root.querySelectorAll('[data-i18n]').forEach(function (el) {
      el.textContent = t(el.getAttribute('data-i18n'));
    });
    root.querySelectorAll('[data-i18n-attr]').forEach(function (el) {
      el.getAttribute('data-i18n-attr').split(';').forEach(function (pair) {
        var p = pair.split(':');
        if (p.length === 2) el.setAttribute(p[0].trim(), t(p[1].trim()));
      });
    });
    document.documentElement.lang = lang;
  }

  function setLang(l) {
    if (l === lang) return;
    lang = l;
    localStorage.setItem('meridian-lang', l);
    load(l).then(function () {
      apply();
      window.dispatchEvent(new CustomEvent('i18n:changed'));
    });
  }

  return {
    ready: ready,
    apply: apply,
    setLang: setLang,
    t: t,
    get lang() { return lang; }
  };
})();
